window.DEX_DATA["sources:backport-295089dddfa3c3e8"]={"json":{"skins":[{"filename":"scientist_m.png"}],"names":[{"name":"亚当"},{"name":"阿基米德"},{"name":"里夫"},{"name":"六眼西奥多"},{"name":"科尼利厄斯"}],"chat":[{"lines":[{"text":"技术进步真让人着迷，有时候我能跟妻子聊个没完。"},{"text":"……没错，是我的妻子！为什么大家都这么惊讶？"}]},{"lines":[{"text":"我正在研究宝可梦表皮色素的特殊变异！"},{"text":"通俗点说，就是异色宝可梦。"}]},{"lines":[{"text":"实验服不太舒服，可做研究还能穿什么呢？"},{"text":"短裤吗？"}]},{"lines":[{"text":"图鉴说卡拉卡拉的妈妈去世了，可如果每只卡拉卡拉的妈妈都去世了……"},{"text":"这数量怎么也算不对啊！"}]},{"lines":[{"text":"我女儿特别想要叶伊布，她正打算给伊布用叶之石。"},{"text":"我该研究一下它的进化条件……"}]}]}};
